package dev.pedro.learning.ecommerce.payment.domain;import io.quarkus.hibernate.orm.panache.PanacheEntityBase;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="payment") public class PaymentEntity extends PanacheEntityBase{@Id public UUID id;@Column(name="order_id",nullable=false,unique=true)public UUID orderId;@Column(nullable=false,precision=19,scale=2)public BigDecimal amount;@Enumerated(EnumType.STRING)@Column(nullable=false)public PaymentStatus status;@Column(name="provider_reference")public String providerReference;@Column(name="failure_reason")public String failureReason;@Column(name="created_at",nullable=false)public Instant createdAt;}